  @doc "Returns a scalar UTF-8 character expression for an exact ECMAScript Unicode property."
  @spec expression(binary(), boolean()) :: binary() | nil
  def expression(name, negative?) do
    case Map.get(@aliases, name) do
      nil ->
        nil

      canonical ->
        expression = Map.fetch!(@expressions, canonical)
        if negative?, do: "(?!" <> expression <> ")[\\s\\S]", else: expression
    end
  end
